    # Final merge pass to ensure route count doesn't stay overly large.
    if len(routes) > max_routes:
        cleanup_rounds = 0
        while len(routes) > max_routes and cleanup_rounds < 25:
            cleanup_rounds += 1
            m = best_merge_pair(routes, capacity)
            if m is None:
                break
            i, j, new_r, delta = m
            if delta <= 0:
                if i < j:
                    routes.pop(j)
                    routes.pop(i)
                else:
                    routes.pop(i)
                    routes.pop(j)
                routes.append(new_r)
                routes[:] = [r for r in routes if r]
            else:
                # allow a small positive if still needed to reduce routes
                base_total = total_cost(routes)
                if delta <= max(0, int(0.005 * base_total / max(1, len(routes)))):
                    if i < j:
                        routes.pop(j)
                        routes.pop(i)
                    else:
                        routes.pop(i)
                        routes.pop(j)
                    routes.append(new_r)
                    routes[:] = [r for r in routes if r]
                else:
                    break

    # Ensure feasibility and return format (no depot)
    return [r for r in routes if r]
